import{_ as r,C as o,o as d,c,a3 as t,E as n}from"./chunks/framework.DAK02U1-.js";const A=JSON.parse('{"title":"系统架构","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"系统架构 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/catter/design/architecture"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/catter/design/architecture"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/design/architecture"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/design/architecture"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/design/architecture"}]]},"headers":[],"relativePath":"zh/catter/design/architecture.md","filePath":"zh/catter/design/architecture.md","lastUpdated":1793198831000}'),i={name:"zh/catter/design/architecture.md"};function l(h,e,s,p,m,u){const a=o("Mermaid");return d(),c("div",null,[e[0]||(e[0]=t('<h1 id="系统架构" tabindex="-1">系统架构 <a class="header-anchor" href="#系统架构" aria-label="Permalink to &quot;系统架构&quot;">​</a></h1><p>Catter 是一个围绕 <strong>捕获后端</strong>（capture backend）展开的构建过程拦截与分析工具。捕获后端是 catter 获取构建命令的方式：构建启动的每条命令都会变成 catter 可处理的事件；在遵从会话中各个 handler 决定的后端下，命令按它们的决定执行——原样执行、修改、丢弃或中止。</p><p>handler 作者只需要理解两件事：</p><ol><li><strong>捕获后端是什么、当前会话用的是哪个</strong> —— 见下文与<a href="./capture-backends">捕获后端</a>。</li><li><strong>会话的生命周期</strong> —— 构建级的开始与结束，以及每条命令运行前和运行后。</li></ol><h2 id="捕获后端" tabindex="-1">捕获后端 <a class="header-anchor" href="#捕获后端" aria-label="Permalink to &quot;捕获后端&quot;">​</a></h2><p>不同平台对&quot;拦截进程创建&quot;的可行性差异很大：在构建的每个进程中加载 hook 最为通用，但有些程序会把它挡在外面（在 macOS 上是 Apple 自带的工具）。因此 catter 把构建命令如何被捕获（即后端）与如何处理这些命令（即会话）分开。每个后端启动构建，并把构建的命令上报给会话；会话让各个 handler 对每条命令做决定，并告诉它们每条命令如何结束。无论由哪个后端上报，handler 看到的都是同样的事件。</p><p>catter 用 <code>hook</code> 后端捕获构建，或者用 <code>--capture</code> 指定的后端：<code>wrapper</code>，它用编译器 shim 覆盖 hook 触及不到的地方；或者 macOS 上的 <code>eslogger</code>、Linux 上的 <code>ptrace</code>，它们只观察构建。指定 <code>--from</code> 时，它不运行构建，而是回放一次录制的构建。handler 从会话的 <code>initialize</code> 消息得知是哪一种：其中的 <code>mode</code> 为后端的名字，或者为 <code>replay</code>，表示录制的构建。各后端能看到什么、支持什么，见<a href="./capture-backends">捕获后端</a>。</p><h2 id="handler" tabindex="-1">Handler <a class="header-anchor" href="#handler" aria-label="Permalink to &quot;Handler&quot;">​</a></h2><p>会话中的 handler 对各条命令做决定，并接收会话事件的通知。它们包括命令运行的内置功能（如果有的话；<code>compile-commands</code>、<code>tree</code>、<code>targets</code>），它在 catter 内部运行，以及通过 <code>--handler</code> 或 <code>--connect</code> 指定的 <a href="./../scripting/handlers">handler</a>，即 catter 用 <a href="./handler-protocol">handler 协议</a>与之通信的程序。这些 handler 组成一条链：内置功能在前，其余按命令行中的顺序排列。</p><h2 id="会话生命周期" tabindex="-1">会话生命周期 <a class="header-anchor" href="#会话生命周期" aria-label="Permalink to &quot;会话生命周期&quot;">​</a></h2>',10)),n(a,{id:"mermaid-39",graph:"sequenceDiagram%0A%20%20%20%20participant%20Handler%0A%20%20%20%20participant%20Catter%20as%20catter%20daemon%0A%20%20%20%20participant%20Backend%20as%20Capture%20backend%0A%20%20%20%20participant%20Build%20as%20Build%20system%0A%0A%20%20%20%20Catter-%3E%3EHandler%3A%20initialize%20(the%20build%2C%20the%20mode)%0A%20%20%20%20Handler--%3E%3ECatter%3A%20What%20it%20wants%20to%20be%20told%0A%20%20%20%20Catter-%3E%3EBackend%3A%20Start%20the%20build%0A%20%20%20%20loop%20For%20each%20captured%20command%0A%20%20%20%20%20%20%20%20Backend-%3E%3ECatter%3A%20Command%20event%0A%20%20%20%20%20%20%20%20Catter-%3E%3EHandler%3A%20command%0A%20%20%20%20%20%20%20%20Handler--%3E%3ECatter%3A%20Action%20(skip%20%2F%20drop%20%2F%20abort%20%2F%20modify%20%2F%20edit)%0A%20%20%20%20%20%20%20%20Catter-%3E%3EBackend%3A%20Execute%20according%20to%20action%0A%20%20%20%20%20%20%20%20Backend-%3E%3ECatter%3A%20Execution%20result%0A%20%20%20%20%20%20%20%20Catter-%3E%3EHandler%3A%20exit%0A%20%20%20%20end%0A%20%20%20%20Backend--%3E%3ECatter%3A%20Build%20process%20finished%0A%20%20%20%20Catter-%3E%3EHandler%3A%20finish%0A"}),e[1]||(e[1]=t('<h3 id="构建级-initialize-finish" tabindex="-1">构建级：initialize / finish <a class="header-anchor" href="#构建级-initialize-finish" aria-label="Permalink to &quot;构建级：initialize / finish&quot;">​</a></h3><p><strong><code>initialize</code></strong> 在构建开始前启动会话：它携带构建命令、构建命令的工作目录、捕获后端，以及命令是否遵从 handler 的决定。handler 在应答中说明它是否对每条命令做决定、想收到哪些事件的通知、想听到哪些命令，以及命令是否携带环境变量和 catter 对它的分析。</p><p><strong><code>finish</code></strong> 在构建结束后到来，携带构建的退出码。handler 在这里写出最终产物。</p><h3 id="命令级-command-error-exit" tabindex="-1">命令级：command / error / exit <a class="header-anchor" href="#命令级-command-error-exit" aria-label="Permalink to &quot;命令级：command / error / exit&quot;">​</a></h3><p><strong><code>command</code></strong> 随每条被捕获的命令到来，在遵从决定的后端下先于命令运行，内容包括命令的工作目录、可执行文件、完整参数、启动它的父命令，以及（handler 要求时）它的环境变量和 catter 对它的分析：它运行的是哪种编译器、归档器或工具，以及它的参数表达了什么。做决定的 handler 以一个动作应答；不做决定的 handler 只接收通知，构建从不等它。</p><p><strong><code>error</code></strong> 在 catter 未能捕获某条命令时取而代之：消息说明原因。</p><p><strong><code>exit</code></strong> 在每条命令执行完毕后到来，携带它的退出码和耗时。handler 可在这里做统计与失败聚合。</p><h2 id="action-handler-语义与执行机制的分层" tabindex="-1">Action：handler 语义与执行机制的分层 <a class="header-anchor" href="#action-handler-语义与执行机制的分层" aria-label="Permalink to &quot;Action：handler 语义与执行机制的分层&quot;">​</a></h2><p>&quot;如何处理一条命令&quot;在 catter 中分两层表达：</p><ol><li><strong>handler 层</strong>（handler 决定的）：<code>skip</code> / <code>drop</code> / <code>abort</code> / <code>modify</code> / <code>edit</code>，语义化、与机制无关。</li><li><strong>协议层</strong>（catter-proxy 执行的，Windows 上则是 hook）：<code>DROP</code> / <code>RUN</code> / <code>FAIL</code>，是具体的执行机制。</li></ol><p>会话负责把 handler 层动作映射到协议层动作，不论命令由哪个后端上报：</p><table tabindex="0"><thead><tr><th>handler 动作</th><th>语义</th><th>协议层映射</th></tr></thead><tbody><tr><td><code>skip</code></td><td>原样执行，catter 不干预</td><td><code>RUN</code>（挂载 hook 执行，子孙命令仍可捕获）</td></tr><tr><td><code>drop</code></td><td>不执行，直接返回退出码 0</td><td><code>DROP</code></td></tr><tr><td><code>abort</code></td><td>中止整个构建并报错</td><td><code>FAIL</code>（这条命令及之后的每条命令都不运行，直接失败）</td></tr><tr><td><code>modify</code></td><td>用修改后的命令替换原命令执行</td><td><code>RUN</code>（携带修改后的命令）</td></tr><tr><td><code>edit</code></td><td>用编辑后的参数执行命令</td><td><code>RUN</code>（携带编辑后的命令）</td></tr></tbody></table><p>需要注意的几点：</p><ul><li><strong><code>skip</code> 不等于&quot;忽略整个子树&quot;</strong>。<code>skip</code> 只是让这条命令照常执行；其子孙命令仍会被捕获，也仍会送达各个 handler。</li><li><strong><code>abort</code> 会结束会话</strong>，与 handler 出错时一样：这条命令以及构建在它之后启动的每条命令都不运行、直接失败；构建结束后，catter 打印原因并以退出码 1 退出。在只观察构建的后端下，出错的 handler 同样会结束会话，但 catter 得知每条命令时它都已启动：构建会一直运行到结束。</li></ul><h2 id="组件与进程" tabindex="-1">组件与进程 <a class="header-anchor" href="#组件与进程" aria-label="Permalink to &quot;组件与进程&quot;">​</a></h2><p>一次 catter 运行会涉及多个进程与组件，它们属于 hook 后端和 wrapper 后端，handler 作者通常无需关心：</p><table tabindex="0"><thead><tr><th>组件</th><th>角色</th></tr></thead><tbody><tr><td><code>catter</code>（守护进程）</td><td>运行会话的各个 handler，通过 IPC 接收命令并返回决策</td></tr><tr><td><code>catter-proxy</code></td><td>在 Linux 和 macOS 上代替钩子拦截到的每条命令运行，也代替 wrapper 后端做了 shim 的每个程序以及构建命令运行（catter 通过它启动构建），并中转 IPC</td></tr><tr><td>hook 共享库</td><td>由 hook 后端加载到构建的每个进程中，以拦截进程创建调用；在 Windows 上由它自己询问守护进程，并启动每个程序</td></tr></tbody></table><p>它们是 <strong>这些后端的实现细节</strong>；后端与会话的分离才是架构的中心。详见<a href="./capture-backends">捕获后端</a>与<a href="./hook-mechanism">钩子机制</a>。</p>',18))])}const f=r(i,[["render",l]]);export{A as __pageData,f as default};
